 const importCsv=async file=>{if(!file)return;const text=await file.text();const lines=text.split(/\r?\n/).filter(Boolean);if(lines.length<2){E("CSV needs a header row and at least one data row.");return}const parse=line=>line.match(/("(?:[^"]|"")*"|[^,]*)(,|$)/g)?.map(x=>x.replace(/,$/,"").replace(/^"|"$/g,"").replaceAll('""','"'))||[];const headers=parse(lines[0]).map(x=>x.trim());const allowed=["regimental_no","full_name","flight_id","year_of_training","rank","wing","phone","guardian_name","guardian_phone"];if(!headers.includes("regimental_no")||!headers.includes("full_name")){E("CSV must include regimental_no and full_name headers.");return}const batch=lines.slice(1).map(line=>{const vals=parse(line);const obj={unit_id:unit,wing:"AIR",year_of_training:1,rank:"Cadet",status:"ACTIVE",guardian_consent:false};headers.forEach((h,i)=>{if(allowed.includes(h)&&vals[i]!==undefined)obj[h]=["year_of_training"].includes(h)?Number(vals[i]):vals[i]});return obj}).filter(x=>x.regimental_no&&x.full_name);B(true);const {error}=await db.from("um_cadets").upsert(batch,{onConflict:"unit_id,regimental_no"});B(false);if(error)E(error.message);else{N("Imported "+batch.length+" cadet rows.");await reload()}};
 const saveAttendance=async()=>{if(!attendanceParade){E("Choose a parade first.");return}AB(true);E("");const rowsPayload=Object.entries(attendanceRows).map(([cadet_id,v])=>({cadet_id,status:v.status||"PRESENT",notes:v.notes||""}));const {data,error}=await db.rpc("um_save_attendance",{p_parade_id:attendanceParade,p_rows:rowsPayload});AB(false);if(error)E(error.message);else N("Attendance saved for "+data+" cadets.");};
 const openAttendance=async paradeId=>{AP(paradeId);const [c,a]=await Promise.all([db.from("um_cadets").select("id,regimental_no,full_name,flight_id,year_of_training").eq("unit_id",unit).eq("status","ACTIVE").order("full_name"),db.from("um_attendance").select("cadet_id,status,notes").eq("unit_id",unit).eq("parade_id",paradeId)]);if(c.error||a.error){E(c.error?.message||a.error?.message);return}const existing=Object.fromEntries((a.data||[]).map(x=>[x.cadet_id,{status:x.status,notes:x.notes}]));AR(Object.fromEntries((c.data||[]).map(x=>[x.id,{...x,...existing[x.id],status:existing[x.id]?.status||"PRESENT"}])));Page("attendance");};
 const doInvite=async e=>{e.preventDefault();B(true);E("");const {data:{session:s}}=await db.auth.getSession();const {data,error}=await db.functions.invoke("unit-manager-admin-users",{body:{action:"invite",...invite},headers:{Authorization:"Bearer "+s.access_token}});B(false);if(error||data?.error){E(data?.error||error.message);return}N(data.message+(data.temporary_password?" Login: "+data.username+" · temporary password: "+data.temporary_password:""));Invite({role:"cadet",full_name:"",email:"",regimental_no:"",year_of_training:"1",flight_id:""});};
 const doBootstrap=async e=>{e.preventDefault();B(true);E("");const {data,error}=await db.functions.invoke("unit-manager-admin-users",{body:{action:"bootstrap",...bootstrap}});B(false);if(error||data?.error){E(data?.error||error.message);return}N(data.message);};
 const visible=useMemo(()=>{const cfg=config[page];if(!cfg)return rows;const q=query.toLowerCase().trim();return rows.filter(r=>!q||cfg.search.some(k=>String(r[k]??"").toLowerCase().includes(q)))},[rows,page,query]);
 const nav=[["dashboard","Command overview",LayoutDashboard],["cadets","Cadet directory",Users],["flights","Flights",Plane],["parades","Parade scheduler",Flag],["attendance","Attendance",ClipboardCheck],["leave","Leave requests",CalendarCheck],["inventory","Kit & inventory",Package],["fitness","Fitness tests",Dumbbell],["syllabus","Certificate syllabus",BookOpen],["progress","Syllabus progress",GraduationCap],["exams","Exam results",GraduationCap],["camps","Camps & events",CalendarDays],["certificates","Certificates",Award],["notifications","Notifications",Bell],["audit","Audit history",ShieldCheck],["settings","Unit settings",Settings],["users","User management",UserCog]];
