 const renderAttendance=()=> <section className="panel"><div className="panel-head"><div><h2>Parade attendance</h2><p>One transactional save · only approved parades · flight scope enforced in PostgreSQL</p></div><button className="btn secondary" onClick={reload}><RefreshCw size={15}/> Refresh</button></div><label className="attendance-select">Approved parade<select value={attendanceParade} onChange={e=>{AR({});openAttendance(e.target.value)}}><option value="">Choose parade…</option>{(lookups.parades||[]).map(r=><option value={r.id} key={r.id}>{DATE(r.parade_date)} · {r.title}</option>)}</select></label>{Object.keys(attendanceRows).length===0?<div className="empty">Choose a parade to load the active cadet roster.</div>:<><div className="table-wrap"><table><thead><tr><th>Regimental no.</th><th>Cadet</th><th>Flight</th><th>Attendance</th><th>Notes</th></tr></thead><tbody>{Object.values(attendanceRows).map(c=><tr key={c.id}><td>{c.regimental_no}</td><td>{c.full_name}</td><td>{lookups.flight?.find(f=>f.id===c.flight_id)?.code||"—"}</td><td><select value={c.status} onChange={e=>AR(o=>({...o,[c.id]:{...o[c.id],status:e.target.value}}))}>{["PRESENT","ABSENT","LATE","LEAVE"].map(s=><option key={s}>{s}</option>)}</select></td><td><input value={c.notes||""} onChange={e=>AR(o=>({...o,[c.id]:{...o[c.id],notes:e.target.value}}))} placeholder="Optional"/></td></tr>)}</tbody></table></div><div className="form-actions"><button className="btn secondary" onClick={()=>AR(o=>Object.fromEntries(Object.entries(o).map(([id,c])=>[id,{...c,status:"PRESENT"}])))}>Mark all present</button><button className="btn primary" disabled={attendanceBusy} onClick={saveAttendance}>{attendanceBusy?"Saving…":"Save attendance"}</button></div></>}</section>;
 const renderInventory=()=> <><section className="panel"><div className="panel-head"><div><h2>Issue kit</h2><p>Inventory allocation locks the stock row and checks available quantity.</p></div></div>{canManage(role)?<form className="form-grid" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);B(true);const {data,error}=await db.rpc("um_issue_item",{p_item_id:f.get("item_id"),p_cadet_id:f.get("cadet_id"),p_qty:Number(f.get("qty")),p_due_date:f.get("due_date")||null});B(false);if(error)E(error.message);else{N("Kit issued. Reference "+data);e.currentTarget.reset();await reload()}}}><label>Item<select name="item_id" required>{rows.map(x=><option value={x.id} key={x.id}>{x.item_code} · {x.name} (available {x.available_qty??x.total_qty})</option>)}</select></label><label>Cadet<select name="cadet_id" required>{lookups.cadet?.map(x=><option key={x.id} value={x.id}>{x.label}</option>)}</select></label><label>Quantity<input name="qty" type="number" min="1" defaultValue="1" required/></label><label>Due date<input name="due_date" type="date"/></label><div className="span-two"><button className="btn primary"><Package size={15}/> Issue item</button></div></form>:<p className="empty">Only officers and administrators may issue or return unit inventory.</p>}</section><section className="panel"><div className="panel-head"><div><h2>Outstanding kit issues</h2><p>Return processing is an audited server-side operation.</p></div><button className="btn secondary" onClick={async()=>{const {data,error}=await db.from("um_inventory_issues").select("*").eq("unit_id",unit).order("created_at",{ascending:false});if(error)E(error.message);else Rows(data||[]);Page("issues")}}>View issued items</button></div></section></>;
